<?php
session_start();require_once '../shared/config.php';if(!isset($_SESSION['admin_id'])){header('Location: login.php');exit;} $db=getDB();$adminId=(int)$_SESSION['admin_id'];$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$type=$_POST['target_type']??'';$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$map=['seller'=>['active','cancelled'],'swap'=>['active','cancelled']];if(!isset($map[$type])||!in_array($action,$map[$type],true)||$id<1)$err='Invalid moderation request.';else{try{$db->beginTransaction();if($type==='seller'){$s=$db->prepare("SELECT id,status FROM seller_listings WHERE id=?");$s->execute([$id]);$row=$s->fetch();if(!$row)throw new Exception('Listing not found.');$db->prepare("UPDATE seller_listings SET status=? WHERE id=?")->execute([$action,$id]);$target='seller_listing';}else{$s=$db->prepare("SELECT id,status FROM swap_listings WHERE id=?");$s->execute([$id]);$row=$s->fetch();if(!$row)throw new Exception('Swap listing not found.');$db->prepare("UPDATE swap_listings SET status=? WHERE id=?")->execute([$action,$id]);$target='swap_listing';}$db->prepare("INSERT INTO admin_actions(admin_id,action,target_type,target_id,notes) VALUES(?,?,?,?,?)")->execute([$adminId,'moderate_'.$type,$target,$id,'Admin marketplace moderation']);$db->commit();$msg='Moderation action saved.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$err='Could not save moderation action.';}}}
$s=$db->query("SELECT sl.*,c.name seller_name FROM seller_listings sl JOIN customers c ON c.id=sl.seller_id WHERE sl.status IN ('active','pending_review') ORDER BY sl.created_at DESC LIMIT 50");$sellers=$s->fetchAll();$s=$db->query("SELECT sw.*,c.name owner_name FROM swap_listings sw JOIN customers c ON c.id=sw.owner_id WHERE sw.status='active' ORDER BY sw.created_at DESC LIMIT 50");$swaps=$s->fetchAll();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketplace Moderation</title><style>body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:20px 30px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none}.main{max-width:1050px;margin:auto;padding:30px}.card{background:#fff;border:1px solid #E8E0D0;padding:20px;margin-bottom:15px}.row{padding:14px 0;border-bottom:1px solid #eee}.btn{padding:8px 11px;border:0;background:#991B1B;color:#fff}.small{font-size:12px;color:#777}.notice{padding:12px;background:#DCFCE7}.error{padding:12px;background:#FEE2E2}</style></head><body><div class="nav"><b>O2O Tradition · Admin</b><div><a href="dashboard.php">Dashboard</a> · <a href="verifications.php">Verification</a> · <a href="logout.php">Logout</a></div></div><main class="main"><h1>Marketplace Moderation</h1><?php if($msg):?><div class="notice"><?=$msg?></div><?php endif;?><?php if($err):?><div class="error"><?=htmlspecialchars($err)?></div><?php endif;?><section class="card"><h2>Seller Listings</h2><?php if(!$sellers):?><p class="small">No active or pending seller listings.</p><?php else:foreach($sellers as $x):?><div class="row"><b><?=htmlspecialchars($x['title'])?></b> · ₹<?=number_format($x['price'],0)?><div class="small">Seller: <?=htmlspecialchars($x['seller_name'])?> · Status: <?=htmlspecialchars($x['status'])?></div><?php if($x['status']==='pending_review'):?><form method="POST" style="display:inline"><input type="hidden" name="target_type" value="seller"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn" name="action" value="cancelled">Reject / Remove</button></form><?php elseif($x['status']==='active'):?><form method="POST"><input type="hidden" name="target_type" value="seller"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn" name="action" value="cancelled">Remove Listing</button></form><?php endif;?></div><?php endforeach;endif;?></section><section class="card"><h2>Active Swap Listings</h2><?php if(!$swaps):?><p class="small">No active swap listings.</p><?php else:foreach($swaps as $x):?><div class="row"><b><?=htmlspecialchars($x['title'])?></b><div class="small">Owner: <?=htmlspecialchars($x['owner_name'])?> · <?=htmlspecialchars($x['condition_label'])?> · <?=htmlspecialchars($x['location']??'')?></div><form method="POST"><input type="hidden" name="target_type" value="swap"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn" name="action" value="cancelled">Remove Listing</button></form></div><?php endforeach;endif;?></section></main></body></html>